// The "one core, not two" guard for @cngx/cli. `packages/mcp/src/core/` is the
// canonical home of the query core (command registry, definitions, loader,
// resolver, snapshot fetch); `packages/cli/src/core/` is a generated byte copy
// so the CLI ships the same core without depending on the MCP SDK.
//
// Unlike doctor-copy-check.mjs, which compares an explicit file list, this walks
// both trees recursively: a new core file is part of the copy the moment it
// exists, so it cannot be forgotten in a list. Spec files are excluded on both
// sides; they run once, in packages/mcp.
//
// Exits non-zero on any missing, extra or differing file, naming
// `npm run cli:sync` as the fix.
//
//   node scripts/cli-core-copy-check.mjs

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { pathToFileURL } from 'node:url';

export const CANONICAL_CORE_DIR = 'packages/mcp/src/core';
export const COPY_CORE_DIR = 'packages/cli/src/core';

/** True for a file that belongs to the core copy (everything except specs). */
export const isCoreFile = (relPath) => !relPath.endsWith('.spec.ts');

/**
 * Every core file under `dir`, as sorted POSIX paths relative to `dir`.
 * A missing directory is an empty tree, so the comparison reports every
 * canonical file as missing instead of throwing.
 */
export function listCoreFiles(dir) {
  if (!existsSync(dir)) {
    return [];
  }
  const files = [];
  const walk = (current) => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      const abs = join(current, entry.name);
      if (entry.isDirectory()) {
        walk(abs);
        continue;
      }
      const rel = relative(dir, abs).split(sep).join('/');
      if (isCoreFile(rel)) {
        files.push(rel);
      }
    }
  };
  walk(dir);
  return files.sort();
}

/**
 * Compare the canonical tree (`listA`, read through `readA`) with the copy
 * (`listB`, `readB`). Readers return the file bytes as a Buffer. Pure apart from
 * the injected readers, so the guard is testable without touching disk.
 */
export function compareTrees(listA, listB, readA, readB) {
  const inCopy = new Set(listB);
  const inCanonical = new Set(listA);
  const mismatches = [];
  for (const file of listA) {
    if (!inCopy.has(file)) {
      mismatches.push({ file, reason: 'missing in the cli copy' });
      continue;
    }
    if (!readA(file).equals(readB(file))) {
      mismatches.push({ file, reason: 'bytes differ' });
    }
  }
  for (const file of listB) {
    if (!inCanonical.has(file)) {
      mismatches.push({ file, reason: 'only in the cli copy' });
    }
  }
  return mismatches;
}

const readUnder = (base) => (file) => readFileSync(resolve(base, file));

function main() {
  const canonical = listCoreFiles(CANONICAL_CORE_DIR);
  const copy = listCoreFiles(COPY_CORE_DIR);
  const mismatches = compareTrees(canonical, copy, readUnder(CANONICAL_CORE_DIR), readUnder(COPY_CORE_DIR));

  if (mismatches.length === 0) {
    process.stdout.write(`cli:copy-check - ${COPY_CORE_DIR} is byte-identical (${canonical.length} files)\n`);
    return;
  }

  process.stdout.write(`cli:copy-check - ${mismatches.length} file(s) diverged from ${CANONICAL_CORE_DIR}:\n`);
  for (const entry of mismatches) {
    process.stdout.write(`  ${entry.file} (${entry.reason})\n`);
  }
  process.stdout.write(`Fix: run \`npm run cli:sync\` to regenerate ${COPY_CORE_DIR} from ${CANONICAL_CORE_DIR}.\n`);
  process.exitCode = 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
